// The shared sync vectors (obsidian-vault-sync task 3.1, design D2): every case
// of internal/vault/testdata/sync, generated by the Go engine's TestSyncVectors,
// replayed step by step against this engine with an in-memory folder and the
// same scripted server. Each step must push the same ops, leave the same files,
// report the same and write the same state as `ot vault`.
import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import { sync } from './engine'
import { MemoryFiles, testCrypter, VectorServer } from './memory'
import { newState, STATE_PATH } from './state'
import type { Op } from './store'
import { LimitError, OwnedError, type Owner } from './types'

interface Step {
  name: string
  now: number
  init?: boolean
  files?: Record<string, string | null>
  server?: Op[]
  generation?: string
  reset?: boolean
  readOnly?: boolean
  dryRun?: boolean
  takeOver?: boolean
  owner?: Owner
  device?: string
  want: { error?: string; message?: string; pushed: Op[]; files: Record<string, string>; report?: unknown; state?: unknown }
}

interface Case {
  name: string
  description: string
  loc: string
  user: string
  encrypted?: boolean
  shared?: string[]
  steps: Step[]
}

const dir = join(new URL('../../../', import.meta.url).pathname, 'internal/vault/testdata/sync')
export const cases: Case[] = readdirSync(dir)
  .filter((f) => f.endsWith('.json'))
  .sort()
  .map((f) => JSON.parse(readFileSync(join(dir, f), 'utf8')) as Case)

const plain = (v: unknown) => JSON.parse(JSON.stringify(v)) as unknown

describe('shared sync vectors', () => {
  it('has the cases', () => expect(cases.length).toBeGreaterThanOrEqual(20))
  for (const c of cases) {
    it(`${c.name}: ${c.description}`, async () => {
      const files = new MemoryFiles()
      const server = new VectorServer(c.shared ?? [])
      for (const step of c.steps) {
        const where = `${c.name} / ${step.name}`
        for (const [p, t] of Object.entries(step.files ?? {})) {
          if (t === null) files.files.delete(p)
          else files.files.set(p, t)
        }
        if (step.reset) server.log = []
        server.log.push(...(step.server ?? []))
        if (step.generation) server.gen = step.generation
        server.now = step.now
        server.received = []
        let report: unknown
        let error = ''
        let message = ''
        try {
          report = await sync({
            files, transport: server, crypter: c.encrypted ? testCrypter : null, userID: c.user, zone: c.loc, now: () => step.now,
            readOnly: step.readOnly, dryRun: step.dryRun, takeOver: step.takeOver, owner: step.owner ?? null,
            state: step.init ? newState('default', 'https://todo.example.com', step.device ?? 'vault:random') : null,
            newDevice: () => step.device ?? 'vault:random',
          })
        } catch (err) {
          if (err instanceof LimitError) error = 'limit'
          else if (err instanceof OwnedError) error = 'owned'
          else throw err
          message = (err as Error).message
        }
        expect({ error, message }, where).toEqual({ error: step.want.error ?? '', message: step.want.message ?? '' })
        expect(plain(server.received), `${where}: pushed`).toEqual(step.want.pushed)
        expect(files.snapshot(), `${where}: files`).toEqual(step.want.files)
        if (step.want.report) expect(plain(report), `${where}: report`).toEqual(step.want.report)
        const st = files.files.get(STATE_PATH)
        expect(st === undefined ? undefined : JSON.parse(st), `${where}: state`).toEqual(step.want.state)
      }
    })
  }
})
